package ae.minilang;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import ae.minilang.Ast.BinOp;
import ae.minilang.LangException.Kind;
import java.math.BigInteger;
import java.util.Random;
import org.junit.jupiter.api.Test;

class ArithTest {
    private static final long[] SAMPLES = {
        0, 1, -1, 2, -2, 3, 7, -7, 100, Long.MAX_VALUE, Long.MIN_VALUE, Long.MAX_VALUE - 1, Long.MIN_VALUE + 1,
        1L << 32, -(1L << 32), 3037000500L};

    private static BigInteger big(long v) {
        return BigInteger.valueOf(v);
    }

    private static boolean fits(BigInteger b) {
        return b.bitLength() <= 63;
    }

    /** Expected value per the spec, computed with BigInteger; null means "must throw OVERFLOW". */
    private static BigInteger oracle(BinOp op, long a, long b) {
        BigInteger x = big(a);
        BigInteger y = big(b);
        BigInteger r = switch (op) {
            case ADD -> x.add(y);
            case SUB -> x.subtract(y);
            case MUL -> x.multiply(y);
            case DIV -> x.divide(y);
            case MOD -> x.remainder(y);
            case LT -> big(a < b ? 1 : 0);
            case LE -> big(a <= b ? 1 : 0);
            case GT -> big(a > b ? 1 : 0);
            case GE -> big(a >= b ? 1 : 0);
            case EQ -> big(a == b ? 1 : 0);
            case NE -> big(a != b ? 1 : 0);
            case AND, OR -> throw new IllegalArgumentException("short-circuit ops are not in Arith");
        };
        return fits(r) ? r : null;
    }

    private static void check(BinOp op, long a, long b) {
        boolean divLike = op == BinOp.DIV || op == BinOp.MOD;
        if (divLike && b == 0) {
            assertEquals(Kind.DIV_ZERO,
                assertThrows(LangException.class, () -> Arith.binary(op, a, b)).kind(), op + " " + a);
            return;
        }
        BigInteger want = oracle(op, a, b);
        String ctx = a + " " + op + " " + b;
        if (want == null) {
            assertEquals(Kind.OVERFLOW,
                assertThrows(LangException.class, () -> Arith.binary(op, a, b), ctx).kind(), ctx);
        } else {
            assertEquals(want.longValueExact(), Arith.binary(op, a, b), ctx);
        }
    }

    @Test
    void edgeGridAgainstBigInteger() {
        BinOp[] ops = {BinOp.ADD, BinOp.SUB, BinOp.MUL, BinOp.DIV, BinOp.MOD,
            BinOp.LT, BinOp.LE, BinOp.GT, BinOp.GE, BinOp.EQ, BinOp.NE};
        for (BinOp op : ops) {
            for (long a : SAMPLES) {
                for (long b : SAMPLES) {
                    check(op, a, b);
                }
            }
        }
    }

    @Test
    void randomAgainstBigInteger() {
        Random rnd = new Random(42);
        BinOp[] ops = {BinOp.ADD, BinOp.SUB, BinOp.MUL, BinOp.DIV, BinOp.MOD};
        for (int i = 0; i < 5000; i++) {
            long a = rnd.nextBoolean() ? rnd.nextLong() : rnd.nextInt(2000) - 1000;
            long b = rnd.nextBoolean() ? rnd.nextLong() : rnd.nextInt(2000) - 1000;
            check(ops[rnd.nextInt(ops.length)], a, b);
        }
    }

    @Test
    void minDividedByMinusOneOverflowsButMinModMinusOneIsZero() {
        assertEquals(Kind.OVERFLOW, assertThrows(LangException.class,
            () -> Arith.binary(BinOp.DIV, Long.MIN_VALUE, -1)).kind());
        assertEquals(0L, Arith.binary(BinOp.MOD, Long.MIN_VALUE, -1));
    }

    @Test
    void divisionTruncatesTowardZeroAndRemainderFollowsDividend() {
        assertEquals(-3L, Arith.binary(BinOp.DIV, -7, 2));
        assertEquals(-1L, Arith.binary(BinOp.MOD, -7, 2));
        assertEquals(1L, Arith.binary(BinOp.MOD, 7, -2));
    }

    @Test
    void unary() {
        assertEquals(-5L, Arith.neg(5));
        assertEquals(Long.MAX_VALUE, Arith.neg(-Long.MAX_VALUE));
        assertEquals(Kind.OVERFLOW,
            assertThrows(LangException.class, () -> Arith.neg(Long.MIN_VALUE)).kind());
        assertEquals(1L, Arith.not(0));
        assertEquals(0L, Arith.not(-9));
    }
}

tests.src/test/java/ae/minilang/DifferentialTe:
package ae.minilang;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import ae.minilang.Lang.Engine;
import ae.minilang.Lang.Result;
import ae.minilang.LangException.Kind;
import java.util.EnumMap;
import java.util.Map;
import org.junit.jupiter.api.Test;

class DifferentialTest {
    private static final int PROGRAMS = 1500;

    private static String source(long seed) {
        return Printer.source(new ProgramGen(seed).generate());
    }

    @Test
    void generatedProgramsAreValid() {
        for (long seed = 0; seed < PROGRAMS; seed++) {
            String src = source(seed);
            Ast.Program p;
            try {
                p = Parser.parse(src);
                Checker.check(p);
            } catch (LangException e) {
                throw new AssertionError("seed " + seed + " invalid: " + e.getMessage() + "\n" + src, e);
            }
        }
    }

    @Test
    void printerRoundTripIsStable() {
        for (long seed = 0; seed < PROGRAMS; seed++) {
            String src = source(seed);
            assertEquals(src, Printer.source(Parser.parse(src)), "seed " + seed);
        }
    }

    @Test
    void allFourEnginesAgree() {
        Map<Object, Integer> mix = new java.util.HashMap<>();
        for (long seed = 0; seed < PROGRAMS; seed++) {
            String src = source(seed);
            Result ref = Lang.run(src, Engine.INTERPRETER);
            for (Engine e : Engine.values()) {
                assertEquals(ref, Lang.run(src, e), "seed " + seed + " engine " + e + "\n" + src);
            }
            mix.merge(ref.error() == null ? "OK" : ref.error(), 1, Integer::sum);
        }
        System.out.println("outcome mix: " + mix);
        assertTrue(mix.getOrDefault("OK", 0) >= PROGRAMS / 5, "too few clean runs: " + mix);
        assertTrue(mix.getOrDefault(Kind.DIV_ZERO, 0) >= 20, "too few DIV_ZERO runs: " + mix);
        assertTrue(mix.getOrDefault(Kind.OVERFLOW, 0) >= 20, "too few OVERFLOW runs: " + mix);
        assertEquals(0, mix.getOrDefault(Kind.STEP_LIMIT, 0), "generated programs must terminate");
        assertEquals(0, mix.getOrDefault(Kind.STACK_OVERFLOW, 0), "generator never recurses");
    }

    @Test
    void generatedProgramsActuallyPrintAndLoop() {
        int printing = 0;
        int loops = 0;
        for (long seed = 0; seed < PROGRAMS; seed++) {
            String src = source(seed);
            if (!Lang.run(src, Engine.INTERPRETER).output().isEmpty()) {
                printing++;
            }
            if (src.contains("while")) {
                loops++;
            }
        }
        assertTrue(printing > PROGRAMS / 3, "printing programs: " + printing);
        assertTrue(loops > PROGRAMS / 5, "programs with loops: " + loops);
    }

    @Test
    void optimisedBytecodeIsNeverLongerAndAlwaysVerifies() {
        int shorter = 0;
        for (long seed = 0; seed < PROGRAMS; seed++) {
            String src = source(seed);
            Bytecode plain = Lang.compile(src, false);
            Bytecode opt = Lang.compile(src, true);
            Verifier.verify(plain);
            Verifier.verify(opt);
            assertTrue(opt.size() <= plain.size(), "seed " + seed + ": " + opt.size() + " > " + plain.size());
            if (opt.size() < plain.size()) {
                shorter++;
            }
        }
        assertTrue(shorter > PROGRAMS / 20, "optimiser rarely helps: " + shorter);
    }

    @Test
    void optimiserIsIdempotentOnGeneratedPrograms() {
        for (long seed = 0; seed < 400; seed++) {
            Ast.Program p = Optimizer.optimize(Parser.parse(source(seed)));
            assertEquals(p, Optimizer.optimize(p), "seed " + seed);
        }
    }

    @Test
    void enginesAgreeUnderTinyStepBudgetsOnlyOnTheKind() {
        // budgets are counted differently per engine, so only "ran out" vs "finished" shapes are compared
        EnumMap<Engine, Kind> kinds = new EnumMap<>(Engine.class);
        for (Engine e : Engine.values()) {
            kinds.put(e, Lang.run("let i = 0; while (i < 1000000) { i = i + 1; } print i;", e, 500).error());
        }
        for (Kind k : kinds.values()) {
            assertEquals(Kind.STEP_LIMIT, k, kinds.toString());
        }
    }
}

package ae.minilang;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

import ae.minilang.Lang.Engine;
import ae.minilang.Lang.Result;
import ae.minilang.LangException.Kind;
import java.util.List;
import org.junit.jupiter.api.Test;

/** Hand-computed behaviour, run on every engine. */
class ExecutionTest {
    private static void ok(String src, Long... expected) {
        for (Engine e : Engine.values()) {
            Result r = Lang.run(src, e);
            assertNull(r.error(), e + " " + src);
            assertEquals(List.of(expected), r.output(), e + " " + src);
        }
    }

    private static void fails(String src, Kind kind, Long... printedBefore) {
        for (Engine e : Engine.values()) {
            Result r = Lang.run(src, e);
            assertEquals(kind, r.error(), e + " " + src);
            assertEquals(List.of(printedBefore), r.output(), e + " " + src);
        }
    }

    @Test
    void arithmeticAndPrecedence() {
        ok("print 1 + 2 * 3; print (1 + 2) * 3; print 10 - 4 - 3; print 7 / 2; print -7 / 2; print -7 % 2;",
            7L, 9L, 3L, 3L, -3L, -1L);
    }

    @Test
    void comparisonsAndLogicYieldZeroOrOne() {
        ok("print 3 < 4; print 4 < 3; print 3 <= 3; print 2 >= 3; print 5 == 5; print 5 != 5; print !0; print !7;"
            + " print 7 && 9; print 0 || 5; print 0 || 0; print 2 > 1 == 1;",
            1L, 0L, 1L, 0L, 1L, 0L, 1L, 0L, 1L, 1L, 0L, 1L);
    }

    @Test
    void shortCircuitSkipsRightSide() {
        String f = "fn t(x) { print x; return x; } ";
        ok(f + "print 0 && t(1);", 0L);
        ok(f + "print 1 || t(2);", 1L);
        ok(f + "print 1 && t(3);", 3L, 1L);
        ok(f + "print 0 || t(4);", 4L, 1L);
        ok(f + "print 0 && 1/0; print 1 || 1/0;", 0L, 1L);
    }

    @Test
    void evaluationOrderIsLeftToRight() {
        String f = "fn t(x) { print x; return x; } fn g(a, b, c) { return a * 100 + b * 10 + c; } ";
        ok(f + "print g(t(1), t(2), t(3));", 1L, 2L, 3L, 123L);
        ok(f + "print t(1) + t(2) * t(3);", 1L, 2L, 3L, 7L);
        fails("fn t(x) { print x; return x; } print t(1) / (t(2) - 2) + t(9);", Kind.DIV_ZERO, 1L, 2L);
    }

    @Test
    void variablesAssignmentAndScopes() {
        ok("let x = 1; { let x = 2; print x; x = 3; print x; } print x;", 2L, 3L, 1L);
        ok("let x = 1; { x = 5; } print x;", 5L);
        ok("let x = 10; { let x = x + 1; print x; } print x;", 11L, 10L);
        ok("let i = 0; while (i < 3) { let sq = i * i; print sq; i = i + 1; }", 0L, 1L, 4L);
        ok("let x = 1; if (x) { let x = 7; print x; } else { print 0; } print x;", 7L, 1L);
    }

    @Test
    void ifElseChains() {
        String f = "fn sign(n) { if (n < 0) { return -1; } else if (n == 0) { return 0; } else { return 1; } } ";
        ok(f + "print sign(-5); print sign(0); print sign(9);", -1L, 0L, 1L);
    }

    @Test
    void whileLoopSum() {
        ok("let i = 1; let s = 0; while (i <= 100) { s = s + i; i = i + 1; } print s;", 5050L);
    }

    @Test
    void recursionFibAndFactorial() {
        String fib = "fn fib(n) { if (n < 2) { return n; } return fib(n - 1) + fib(n - 2); } ";
        ok(fib + "print fib(0); print fib(1); print fib(10); print fib(15);", 0L, 1L, 55L, 610L);
        String fact = "fn fact(n) { if (n <= 1) { return 1; } return n * fact(n - 1); } ";
        ok(fact + "print fact(20);", 2432902008176640000L);
        fails(fact + "print fact(5); print fact(21);", Kind.OVERFLOW, 120L);
    }

    @Test
    void mutualRecursionAndParameterIsolation() {
        ok("fn even(n) { if (n == 0) { return 1; } return odd(n - 1); }"
            + "fn odd(n) { if (n == 0) { return 0; } return even(n - 1); }"
            + "print even(10); print odd(7); print even(7);", 1L, 1L, 0L);
        ok("fn bump(a) { a = a + 1; return a; } let x = 5; print bump(x); print x;", 6L, 5L);
    }

    @Test
    void fallingOffTheEndAndBareReturnYieldZero() {
        ok("fn a() { } fn b() { return; } fn c() { let z = 9; } print a(); print b(); print c();", 0L, 0L, 0L);
    }

    @Test
    void topLevelReturnHaltsProgram() {
        ok("print 1; return; print 2;", 1L);
        ok("print 1; if (1) { return 5; } print 2;", 1L);
        ok("let i = 0; while (1) { i = i + 1; if (i == 3) { return; } print i; }", 1L, 2L);
    }

    @Test
    void returnInsideLoopLeavesFunction() {
        ok("fn find(n) { let i = 0; while (i < 100) { if (i * i >= n) { return i; } i = i + 1; } return -1; }"
            + "print find(50); print find(10000);", 8L, -1L);
    }

    @Test
    void arithmeticErrorsKeepEarlierOutput() {
        fails("print 1; print 5 / 0; print 2;", Kind.DIV_ZERO, 1L);
        fails("print 1; print 5 % (3 - 3);", Kind.DIV_ZERO, 1L);
        fails("print 9223372036854775807; print 9223372036854775807 + 1;", Kind.OVERFLOW, Long.MAX_VALUE);
        fails("print -(-9223372036854775808);", Kind.OVERFLOW);
        fails("print (-9223372036854775808) / (0 - 1);", Kind.OVERFLOW);
        ok("print -9223372036854775808; print (-9223372036854775808) % (0 - 1);", Long.MIN_VALUE, 0L);
    }

    @Test
    void callDepthLimitIsExactlyOneHundredFrames() {
        String d = "fn d(n) { if (n == 0) { return 0; } return d(n - 1) + 1; } ";
        ok(d + "print d(98);", 98L);
        fails(d + "print 7; print d(99);", Kind.STACK_OVERFLOW, 7L);
        fails("fn r(n) { return r(n + 1); } r(0);", Kind.STACK_OVERFLOW);
    }

    @Test
    void stepBudgetStopsRunawayLoops() {
        for (Engine e : Engine.values()) {
            Result r = Lang.run("let i = 0; while (1) { i = i + 1; }", e, 10_000);
            assertEquals(Kind.STEP_LIMIT, r.error(), e.toString());
        }
        for (Engine e : Engine.values()) {
            Result r = Lang.run("let i = 0; while (i < 50) { i = i + 1; } print i;", e, 10_000);
            assertEquals(List.of(50L), r.output(), e.toString());
        }
    }

    @Test
    void staticErrorsProduceNoOutput() {
        for (Engine e : Engine.values()) {
            assertEquals(Kind.NAME, Lang.run("print 1; print zz;", e).error());
            assertEquals(List.of(), Lang.run("print 1; print zz;", e).output());
            assertEquals(Kind.SYNTAX, Lang.run("print 1 +;", e).error());
            assertEquals(Kind.ARITY, Lang.run("fn f(a) { return a; } print f();", e).error());
        }
    }
}

tests.src/test/java/ae/minilang/FrontEndTest.j:
package ae.minilang;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import ae.minilang.LangException.Kind;
import java.util.List;
import org.junit.jupiter.api.Test;

class FrontEndTest {
    private static String show(String src) {
        return Printer.source(Parser.parse(src));
    }

    private static String mainOf(String src) {
        return show(src).trim();
    }

    private static LangException fails(String src) {
        return assertThrows(LangException.class, () -> Checker.check(Parser.parse(src)), src);
    }

    @Test
    void lexerPositionsAndComments() {
        List<Lexer.Token> t = Lexer.lex("let x = 1; // c\n  y");
        assertEquals("let", t.get(0).text());
        assertEquals(1, t.get(0).col());
        Lexer.Token y = t.get(5);
        assertEquals("y", y.text());
        assertEquals(2, y.line());
        assertEquals(3, y.col());
        assertEquals(Lexer.Type.EOF, t.get(6).type());
    }

    @Test
    void lexerRejectsStrayCharacters() {
        LangException e = assertThrows(LangException.class, () -> Lexer.lex("a & b"));
        assertEquals(Kind.SYNTAX, e.kind());
        assertTrue(e.getMessage().startsWith("line 1, col 3"), e.getMessage());
        assertThrows(LangException.class, () -> Lexer.lex("12ab"));
    }

    @Test
    void precedenceMultiplicationOverAddition() {
        assertEquals("(1 + (2 * 3));", mainOf("1 + 2 * 3;"));
        assertEquals("((1 * 2) + 3);", mainOf("1 * 2 + 3;"));
    }

    @Test
    void additionIsLeftAssociative() {
        assertEquals("((1 - 2) - 3);", mainOf("1 - 2 - 3;"));
        assertEquals("((8 / 4) / 2);", mainOf("8 / 4 / 2;"));
    }

    @Test
    void logicalAndBindsTighterThanOr() {
        assertEquals("(1 || (2 && 3));", mainOf("1 || 2 && 3;"));
        assertEquals("((1 && 2) || 3);", mainOf("1 && 2 || 3;"));
    }

    @Test
    void comparisonBetweenArithmeticAndEquality() {
        assertEquals("((1 + 2) < (3 * 4));", mainOf("1 + 2 < 3 * 4;"));
        assertEquals("((1 < 2) == (3 < 4));", mainOf("1 < 2 == 3 < 4;"));
    }

    @Test
    void unaryBindsTighterThanBinary() {
        assertEquals("((-1) * 2);", mainOf("-1 * 2;"));
        assertEquals("(!(1 + 2));", mainOf("!(1 + 2);"));
        assertEquals("((!1) + 2);", mainOf("!1 + 2;"));
        assertEquals("(-(-3));", mainOf("--3;"));
    }

    @Test
    void minimumLiteralParsesAndOnePastItIsRejected() {
        assertEquals("(-9223372036854775808);", mainOf("-9223372036854775808;"));
        LangException e = assertThrows(LangException.class, () -> Parser.parse("9223372036854775808;"));
        assertEquals(Kind.SYNTAX, e.kind());
        assertEquals("9223372036854775807;", mainOf("9223372036854775807;"));
    }

    @Test
    void callsAssignmentsAndElseIf() {
        assertEquals("f(1, (2 + 3));", mainOf("f(1, 2+3);"));
        assertEquals("g();", mainOf("g();"));
        String s = show("if (a) { x = 1; } else if (b) { x = 2; } else { x = 3; }");
        assertTrue(s.contains("if (a) {"), s);
        assertTrue(s.contains("else { if (b) {"), s);
    }

    @Test
    void functionsAreHoistedOutOfMainOrder() {
        Ast.Program p = Parser.parse("print 1; fn f() { return 2; } print 3;");
        assertEquals(1, p.funcs().size());
        assertEquals(2, p.main().size());
    }

    @Test
    void syntaxErrorsCarryPositions() {
        LangException e = assertThrows(LangException.class, () -> Parser.parse("let x = ;"));
        assertEquals(Kind.SYNTAX, e.kind());
        assertTrue(e.getMessage().startsWith("line 1, col 9"), e.getMessage());
        e = assertThrows(LangException.class, () -> Parser.parse("print 1\nprint 2;"));
        assertTrue(e.getMessage().startsWith("line 2, col 1"), e.getMessage());
        assertThrows(LangException.class, () -> Parser.parse("let if = 1;"));
        assertThrows(LangException.class, () -> Parser.parse("{ fn f() {} }"));
        assertThrows(LangException.class, () -> Parser.parse("x + 1 = 2;"));
        assertThrows(LangException.class, () -> Parser.parse("if (1) print 1;"));
    }

    @Test
    void checkerRejectsUnknownAndDuplicateNames() {
        assertEquals(Kind.NAME, fails("print x;").kind());
        assertEquals(Kind.NAME, fails("x = 1;").kind());
        assertEquals(Kind.NAME, fails("let x = 1; let x = 2;").kind());
        assertEquals(Kind.NAME, fails("f();").kind());
        assertEquals(Kind.NAME, fails("fn f() {} fn f() {}").kind());
        assertEquals(Kind.NAME, fails("fn f(a, a) {}").kind());
        assertEquals(Kind.NAME, fails("fn f(a) { let a = 1; }").kind());
        assertEquals(Kind.NAME, fails("fn f() { print y; } let y = 1;").kind());
    }

    @Test
    void checkerArityAndPositions() {
        LangException e = fails("fn f(a, b) { return a; }\nprint f(1);");
        assertEquals(Kind.ARITY, e.kind());
        assertTrue(e.getMessage().startsWith("line 2, col 7"), e.getMessage());
        e = fails("let a = 1;\n  print b;");
        assertTrue(e.getMessage().startsWith("line 2, col 9"), e.getMessage());
    }

    @Test
    void checkerScopingRules() {
        Checker.check(Parser.parse("let x = 1; { let x = 2; } let y = x + 1;"));
        Checker.check(Parser.parse("let x = 1; let x2 = 2; { let x = x + 1; print x; }"));
        Checker.check(Parser.parse("fn even(n) { if (n == 0) { return 1; } return odd(n - 1); }"
                + "fn odd(n) { if (n == 0) { return 0; } return even(n - 1); } print even(4);"));
        assertEquals(Kind.NAME, fails("{ let t = 1; } print t;").kind());
        assertEquals(Kind.NAME, fails("while (0) { let t = 1; } print t;").kind());
    }
}

package ae.minilang;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class OptimizerTest {
    private static String opt(String src) {
        return Printer.source(Optimizer.optimize(Parser.parse(src))).trim();
    }

    @Test
    void foldsConstants() {
        assertEquals("print 7;", opt("print 1 + 2 * 3;"));
        assertEquals("print (-4);", opt("print 3 - 7;"));
        assertEquals("print 1;", opt("print !0 && 5 > 2;"));
        assertEquals("print 0;", opt("print !5 || 0 == 1;"));
    }

    @Test
    void neverFoldsAnErrorAway() {
        assertEquals("print (1 / 0);", opt("print 1 / 0;"));
        assertEquals("print (9223372036854775807 + 1);", opt("print 9223372036854775807 + 1;"));
        assertEquals("print (-(-9223372036854775808));", opt("print -(-9223372036854775808);"));
        assertEquals("print (5 % 0);", opt("print 5 % 0;"));
    }

    @Test
    void identitiesKeepTheOperandOnly() {
        assertEquals("let x = 5;\nprint (x + x);", opt("let x = 5; print (x * 1) + (0 + x);"));
        assertEquals("let x = 5;\nprint x;", opt("let x = 5; print (x - 0) / 1 + 0;"));
        assertEquals("let x = 5;\nprint (x % 1);", opt("let x = 5; print x % 1;"));
        // x * 0 may hide an overflow or a call inside x, so it must not collapse
        assertEquals("let x = 5;\nprint (x * 0);", opt("let x = 5; print x * 0;"));
        assertEquals("let x = 5;\nprint (-(-x));", opt("let x = 5; print -(-x);"));
    }

    @Test
    void shortCircuitFolding() {
        String f = "fn f() { print 9; return 1; } ";
        assertEquals("fn f() { print 9; return 1; }\nprint 0;", opt(f + "print 0 && f();"));
        assertEquals("fn f() { print 9; return 1; }\nprint 1;", opt(f + "print 1 || f();"));
        assertEquals("fn f() { print 9; return 1; }\nprint (f() != 0);", opt(f + "print 1 && f();"));
        assertEquals("fn f() { print 9; return 1; }\nprint (f() < 2);", opt(f + "print 0 || f() < 2;"));
        assertEquals("fn f() { print 9; return 1; }\nprint (f() && 0);", opt(f + "print f() && 0;"));
    }

    @Test
    void deadBranchesAndLoops() {
        assertEquals("print 2;", opt("if (0) { print 1; } else { print 2; }"));
        assertEquals("print 1;", opt("if (3 - 2) { print 1; } else { print 2; }"));
        assertEquals("{ let a = 1; print a; }", opt("if (1) { let a = 1; print a; }"));
        assertEquals("", opt("if (0) { print 1; }"));
        assertEquals("", opt("while (0) { print 1; }"));
        assertEquals("let i = 0;\nwhile (1) { i = (i + 1); }", opt("let i = 0; while (1) { i = i + 1; }"));
    }

    @Test
    void pureStatementsDisappearButEffectfulOnesStay() {
        String f = "fn f() { return 1; } ";
        assertEquals("fn f() { return 1; }", opt(f + "5; f;".replace("f;", "")));
        assertEquals("let x = 1;\nlet y = 2;", opt("let x = 1; x; let y = 2;"));
        assertEquals("let x = 1;\n(x + 1);", opt("let x = 1; x + 1;"));
        assertEquals("fn f() { return 1; }\nf();", opt(f + "f();"));
        assertEquals("fn f() { return 1; }\nf();", opt(f + "if (f()) { } else { }"));
    }

    @Test
    void codeAfterReturnIsRemoved() {
        assertEquals("fn f() { return 1; }", opt("fn f() { return 1; print 2; }"));
        assertEquals("return;", opt("return; print 1; let x = 2;"));
        assertEquals("fn f() { return 1; }", opt("fn f() { { return 1; } print 2; }"));
    }

    @Test
    void blocksKeepScopeOnlyWhenTheyDeclare() {
        assertEquals("print 1;", opt("{ print 1; }"));
        assertEquals("let x = 1;\n{ let x = 2; print x; }\nprint x;", opt("let x = 1; { let x = 2; print x; } print x;"));
        assertEquals("", opt("{ { } }"));
    }

    @Test
    void optimiserIsIdempotent() {
        String[] srcs = {
            "if (1) { if (0) { print 1; } else { print 2; } } print 0 || 1 && 5;",
            "let i = 0; while (i < 2 + 1) { { i = i + 1; } if (i == 9 - 8) { return; } }"};
        for (String s : srcs) {
            String once = opt(s);
            assertEquals(once, opt(once), s);
        }
    }
}

